// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, createCollection, hideCollectionInApp, deleteCollection } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(167000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on("pageerror", (error) => pageErrors.push(error.message));

    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(baseUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    const response0 = await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    expect(response0.status()).toBe(200);

    await page.getByRole("button", { name: "Remind Later" }).click();
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);

    const playwrightRequest1: Record<string, any> = {"collection": "qa_hidden_state"};

    const response1 = await createCollection(page, getValue(playwrightRequest1, "collection"));
    expect(response1.status()).toBe(200);
    expect(getValue(await response1.text(), "data.collection")).toBe(getValue(playwrightRequest1, "collection"));

    const response2 = await hideCollectionInApp(page);
    expect(response2.status()).toBe(200);
    expect(getValue(await response2.text(), "data.meta.hidden")).toBe(true);

    await page.getByRole("link").nth(3).click();
    await expect(page).toHaveURL(`${baseUrl}/admin/content`);
    await expect(page.locator('[data-testid="empty-collections"]')).toHaveCount(0);
    await expect(page.locator("#module-navigation").getByRole("link")).toHaveCount(0);
    await expect(page.locator("main").getByRole("heading")).toHaveText("No Collections");

    const url0 = `${baseUrl}/admin/settings/data-model/${getValue(await response2.text(), "data.schema.name")}`;
    await page.goto(url0);
    await deleteCollection(page);

    expect(pageErrors).toHaveLength(0);
});
